from pathlib import Path
import json
modules=[]; questions=[]
def unit(id,title,en,intro,sources,lessons,formula,mins=15):
 modules.append(dict(id=id,title=title,en=en,intro=intro,sources=sources,lessons=[dict(title=t,body=b,example=e,steps=s,trap=x) for t,b,e,s,x in lessons],formula=formula,minutes=mins,foundation=len(modules)<4))
def mc(m,key,p,opts,c,h,steps):
 questions.append(dict(id=f'{m}-{key}',moduleId=m,type='mc',prompt=p,options=opts,correct=c,hint=h,steps=steps,answer=opts[c]))
def calc(m,key,p,fields,h,steps):
 questions.append(dict(id=f'{m}-{key}',moduleId=m,type='calc',prompt=p,fields=[dict(label=l,value=v,tolerance=.002) for l,v in fields],hint=h,steps=steps,answer='；'.join(f'{l} = {v}' for l,v in fields)))
def written(m,key,typ,p,answer,rubric,h):
 questions.append(dict(id=f'{m}-{key}',moduleId=m,type=typ,prompt=p,answer=answer,rubric=rubric,hint=h,steps=rubric))
unit('tensor','先學會讀數字','Tensors & matrices','不用先學微積分。先分清楚一個數、一排數、一張表，以及每個維度在數甚麼。',['Lect-1-Lab-Handout.pdf · pp.7–13,20','Lab-02-Data.pdf · pp.1–6','Lect-2-Homework.pdf · pp.4–5,12–15'],[
('Tensor 是甚麼？','Tensor 是裝數字的容器。scalar 是一個數；vector 是一排數；matrix 是有行有列的表。shape 是各軸長度，並非數值本身。rank 是軸的數目。dtype 表示每格數字的類型，device 表示放在 CPU 還是 GPU。','[[1,2,3],[4,5,6]] 的 shape 和元素數？',['有 2 行，每行 3 格，所以 shape=(2,3)。','rank=2，元素數=2×3=6。','torch.tensor(4.) 的 shape=()，仍有 1 個元素。'],'shape=(3,) 是長度 3 的 vector；(1,3) 是一行三列，rank 不同。'),
('Matrix 乘法先看尺寸','A @ B 是每一行對每一列做內積。A 的列數必須等於 B 的行數。(m,k)@(k,n) 得到 (m,n)。A * B 通常是逐元素相乘，意思不同。','A=[[1,2],[3,4]]，b=[[2],[1]]，A@b？',['第一行：1×2+2×1=4。','第二行：3×2+4×1=10。','結果 [[4],[10]]，shape=(2,1)。'],'@ 不是同位置數字相乘；不要把 matrix transpose 和 reshape 當成同一件事。'),
('索引、batch 和資料佈局','Python 從 0 開始數。m[:,1] 取所有行的第二列。m[1:] 取第二行起。batch 是一次處理多個例子；PyTorch 圖片常用 (B,C,H,W)，sequence 常用 (B,T,F)。NumPy 圖片常是 (H,W,C)，要讀清題設。','8 張 RGB 圖片，每張 16×16，用 BCHW 表示？',['B=8、C=3、H=W=16，shape=(8,3,16,16)。','共 8×3×16×16=6144 個值。','unsqueeze 加一個長度 1 的軸；reshape 不會改變元素總數。'],'不要把 channels 當 batch，也不要用 reshape 代替 permute 轉換 HWC→CHW。')],['(m,k) @ (k,n) → (m,n)','元素數 = shape 各維度相乘','image: (B,C,H,W)；sequence: (B,T,F)'])
