calc('lstm','c1','c_prev=0.8,f=0.5,i=0.25,g=0.4,o=0.6。',[('舊貢獻',0.4),('新貢獻',0.1),('c',0.5),('h',0.277270)],'c是兩個乘積相加，h再經tanh與output gate。',['0.5×0.8=0.4。','0.25×0.4=0.1；c=0.5。','h=0.6×tanh(0.5)≈0.277。'])
calc('lstm','c2','c0=0.6；step1 f=.5,i=.4,g=.5；step2 f=.8,i=.25,g=-.4。',[('c1',0.5),('step2舊貢獻',0.4),('step2新貢獻',-0.1),('c2',0.3)],'第二步沿用c1，不是重新拿c0。',['c1=.5×.6+.4×.5=.5。','c2=.8×.5+.25×(-.4)=.3。'])
